const CONTEXT_INSTRUCTION =
  '### CONTEXT GUIDANCE\nUse the provided context to inform the tone and style, but do not output the context itself.';

export interface BuiltPrompt {
  systemPrompt: string;
  userPrompt: string;
}

export function buildRewriterPrompt(
  inputText: string,
  options: Partial<AIRewriterCreateOptions> = {}
): BuiltPrompt {
  const tone = options.tone || 'as-is';
  const format = options.format || 'as-is';
  const length = options.length || 'as-is';
  const sharedContext = options.sharedContext?.trim() || '';
  const targetLanguageName = getLanguageDisplayName(options.outputLanguage);

  const key = `${tone}|${format}|${length}`;
  let systemPrompt =
    REWRITER_PROMPT_LOOKUP[key] || REWRITER_PROMPT_LOOKUP['as-is|as-is|as-is'];

  // Replace hardcoded Japanese language instruction with selected target language or auto
  const languageReplacement = targetLanguageName
    ? `2.  **LANGUAGE INTEGRITY**: The output must be generated **exclusively** in **${targetLanguageName}**.\n    *   **Naturalness**: Ensure native-level phrasing. Avoid robotic, "translated", or unnatural sentence structures.`
    : '2.  **LANGUAGE INTEGRITY**: The output must be generated in the same language as the source TEXT unless explicitly requested otherwise.\n    *   **Naturalness**: Ensure native-level phrasing. Avoid robotic, "translated", or unnatural sentence structures.';

  const targetLanguageLabel = targetLanguageName
    ? `### TARGET LANGUAGE: **${targetLanguageName}**`
    : '### TARGET LANGUAGE: Same language as source TEXT';

  systemPrompt = systemPrompt.replace(
    /2\.\s+\*\*LANGUAGE INTEGRITY\*\*: The output must be generated \*\*exclusively\*\* in \*\*Japanese\*\.\s+\*\s+\*\*SCRIPT LOCK\*\*: Do not include characters from other scripts \(e\.g\., \*\*NO\*\* Cyrillic, Hanzi, or English words in non-English text unless they are proper nouns explicitly in the source\)\.\s+\*\s+\*\*Naturalness\*\*: Ensure native-level phrasing\. Avoid robotic, "translated", or unnatural sentence structures\./g,
    languageReplacement
  );

  systemPrompt = systemPrompt.replace(
    /### TARGET LANGUAGE: \*\*Japanese\*\*/g,
    targetLanguageLabel
  );

  if (!sharedContext) {
    systemPrompt = systemPrompt.replace(CONTEXT_INSTRUCTION, '').trim();
  }

  let userPrompt = '';
  if (sharedContext) {
    userPrompt = `CONTEXT: ${sharedContext}\n\nTEXT: ${inputText}`;
  } else {
    userPrompt = `TEXT: ${inputText}`;
  }

  return {
    systemPrompt,
    userPrompt,
  };
}
